use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WG: u32 = 256;
const MAX_DIM: u32 = 65535;

fn parse_input(path: &str) -> Result<(u32, u32, u32), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let nums: Vec<u32> = text
        .split_whitespace()
        .map(|t| t.parse::<u32>().map_err(|e| format!("bad number {t:?}: {e}")))
        .collect::<Result<_, _>>()?;
    match nums[..] {
        [count, seed, bins, ..] if (1..=256).contains(&bins) => Ok((count, seed, bins)),
        _ => Err("expected `<count> <seed> <bins>` with bins in 1..=256".to_string()),
    }
}

fn run(count: u32, seed: u32, bins: u32) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram"),
        source: wgpu::ShaderSource::Wgsl(include_str!("shader.wgsl").into()),
    });

    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck_u32(&[count, seed, bins, 0]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let values = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("values"),
        size: (count.max(1) as u64) * 4,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let hist_size = 256 * 4;
    let hist = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("hist"),
        size: hist_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: hist_size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let storage_entry = |binding| wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only: false },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    };
    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: None,
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            storage_entry(1),
            storage_entry(2),
        ],
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: values.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 2, resource: hist.as_entire_binding() },
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: None,
        bind_group_layouts: &[&layout],
        push_constant_ranges: &[],
    });
    let make = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let generate = make("generate");
    let counter = make("count");

    let groups = count.div_ceil(WG);
    let (gx, gy) = (groups.clamp(1, MAX_DIM), groups.div_ceil(MAX_DIM).max(1));
    // With gy > 1 the shader's row stride is gx * WG, so every row must have the
    // full gx groups; the bounds check against `count` discards the excess.
    let mut encoder = device.create_command_encoder(&Default::default());
    encoder.clear_buffer(&hist, 0, None);
    if count > 0 {
        for (pipe, name) in [(&generate, "generate"), (&counter, "count")] {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some(name),
                timestamp_writes: None,
            });
            pass.set_pipeline(pipe);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(gx, gy, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&hist, 0, &readback, 0, hist_size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("poll failed: {e:?}"))?;
    rx.recv()
        .map_err(|e| e.to_string())?
        .map_err(|e| format!("map failed: {e}"))?;
    let data = slice.get_mapped_range();
    let out = data
        .chunks_exact(4)
        .take(bins as usize)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn bytemuck_u32(v: &[u32]) -> &[u8] {
    // SAFETY: u32 has no padding and u8 has alignment 1.
    unsafe { std::slice::from_raw_parts(v.as_ptr().cast::<u8>(), std::mem::size_of_val(v)) }
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-histogram <input-file>");
        return ExitCode::FAILURE;
    };
    let result = parse_input(&path).and_then(|(count, seed, bins)| {
        run(count, seed, bins).map(|h| (count, h))
    });
    match result {
        Ok((count, hist)) => {
            let mut out = String::new();
            for (i, n) in hist.iter().enumerate() {
                out.push_str(&format!("BIN {i} {n}\n"));
            }
            out.push_str(&format!("TOTAL {count}\n"));
            print!("{out}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
